query GetPostsByIds($in: [ID], $first: Int!) {
  posts(first: $first, where: {in: $in, orderby: {field: IN, order: ASC}}) {
    nodes {
      databaseId
      slug
      title(format: RENDERED)
      excerpt(format: RENDERED)
      featuredImage {
        node {
          sourceUrl
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
